          "title": "快速交通通达性",
          "max": 7,
          "mode": "single",
          "step": 1,
          "note": "有两种或两种以上快速交通方式直达（连通）景区所在地（县级行政单元）或景区周边交通枢纽",
          "sourceText": "有两种或两种以上快速交通方式直达（连通）景区所在地（县级行政单元）或景区周边交通枢纽\n快速交通包括航空、高铁、城际铁路、高速公路、快速路等交通方式\n有一种快速交通方式直达（连通）景区所在地（县级行政单元）或景区周边交通枢纽 | 5\n无快速交通方式直达（连通）景区所在地（县级行政单元）或景区周边交通枢纽 | 3",
