          "sourceText": "交通非常便捷，主要交通场站或城镇中心至景区入口的距离在 20km 以内，或通行时间在 1 小时内\n通行时间可查询非高峰时段的当地主要交通场站或城镇中心至景区入口的导航时间\n交通比较便捷，主要交通场站或城镇中心至景区入口的距离在 50km 以内，或通行时间在 1~2 小时内 | 7\n交通便捷性一般，主要交通场站或城镇中心至景区入口的距离在 100km 以内，或通行时间在 2~3 小时内 | 5\n交通不够便捷，主要交通场站或城镇中心至景区入口的距离在 100km 以上，或通行时间在 3 小时以上 | 3",
